-- Onboarding v1 (docs/plan.md §1.125; docs/cases-plan.md §4–§5): the client file and its facts
-- and saved starts (operator-only tables, as deal is), the deal's client file, and a client's
-- intake with its people, answers, scope and log (tenant tables, forced RLS). Also the knowledge
-- base's `about` kind and the onboarding emails' notification kinds. Additive only, so the
-- previous Worker keeps working: new tables, a nullable column, two widened checks. Generated by
-- drizzle-kit; the grants and row-level security at the end are hand-written.
CREATE TABLE "client_fact" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"file_id" uuid NOT NULL,
	"section" text NOT NULL,
	"text" text NOT NULL,
	"source_kind" text NOT NULL,
	"sources" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"sureness" text DEFAULT 'heard' NOT NULL,
	"audience" text DEFAULT 'ours' NOT NULL,
	"replaces_id" uuid,
	"actor" text NOT NULL,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "client_fact_section_check" CHECK ("client_fact"."section" in ('business', 'people', 'systems', 'volumes', 'processes', 'pains', 'limits', 'notes')),
	CONSTRAINT "client_fact_text_check" CHECK (char_length("client_fact"."text") between 1 and 2000),
	CONSTRAINT "client_fact_source_kind_check" CHECK ("client_fact"."source_kind" in ('call', 'note', 'email', 'document', 'website', 'intake', 'tool', 'run', 'other')),
	CONSTRAINT "client_fact_sources_check" CHECK (jsonb_typeof("client_fact"."sources") = 'array'),
	CONSTRAINT "client_fact_sureness_check" CHECK ("client_fact"."sureness" in ('heard', 'seen', 'confirmed')),
	CONSTRAINT "client_fact_audience_check" CHECK ("client_fact"."audience" in ('theirs', 'ours')),
	CONSTRAINT "client_fact_actor_check" CHECK ("client_fact"."actor" in ('operator', 'reggie', 'client', 'system')),
	CONSTRAINT "client_fact_replaces_check" CHECK ("client_fact"."replaces_id" is null or "client_fact"."replaces_id" <> "client_fact"."id")
);
