-- Row-level security, forced. A client file: operator sessions only, and only for the clients the
-- session serves where it names one (a prospect's names none). A client's session never sees one.
ALTER TABLE client_file ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
ALTER TABLE client_file FORCE ROW LEVEL SECURITY;
--> statement-breakpoint
CREATE POLICY operator_only ON client_file FOR ALL TO PUBLIC
  USING (app_is_operator() AND (client_id IS NULL OR client_id = any(app_tenant_ids())))
  WITH CHECK (app_is_operator() AND (client_id IS NULL OR client_id = any(app_tenant_ids())));
--> statement-breakpoint
